{
  "is_open_solicitation": true,
  "buyer": "Government Authority located in Massachusetts (unspecified agency)",
  "title": "SW-121256 - USA (Massachusetts) - Administrative Services Organization",
  "due_date": "2026-12-10",
  "fit_score": 55,
  "why_fit": [
    "Massachusetts-based digital agency with web development and hosting capabilities",
    "Experience building custom web applications and mobile apps (Flutter + backend)",
    "Offers managed hosting with daily backups, SSL, and maintenance",
    "Local presence in Massachusetts matches onshore requirement",
    "Hand-coded, fast websites aligned with modern web standards"
  ],
  "gaps": [
    "No explicit experience with Family Resource Centers or similar social services",
    "Communication strategy scope (marketing, outreach, media relations, branding) beyond local SEO",
    "Administrative support for FRCs may require staffing/processes not offered",
    "Government contracting may require certifications, bonding, or past performance not demonstrated",
    "RFP document costs $7 to download; full requirements unknown"
  ],
  "requirements": [
    "Digital proposal submission via email or online",
    "Questions must be submitted by November 2, 2026",
    "Proposal due December 10, 2026",
    "Onshore (USA organization only)",
    "Work performed offsite"
  ],
  "evidence": [
    {
      "claim": "RFP seeks vendor for administrative services organization including web-based system",
      "quote": "Vendor needs to provide administrative services organization to the government authority located in Massachusetts. This web-based system should be configurable and support multiple related data relationships."
    },
    {
      "claim": "System must include customizable forms, reporting, dashboards, and reminders",
      "quote": "It should include: customizable data collection forms; reporting and dashboard capabilities for individual clients, groups of clients or services, Family Resource Center (FRC), and across multiple Family Resource Centers; and reminders for follow-up."
    },
    {
      "claim": "Scope includes communication strategy, web application development, hosting, and content management",
      "quote": "Develop and implement a comprehensive communication strategy for the FRCs, which shall include but not be limited to marketing, outreach, media relations, messaging and branding development. Develop, host, maintain and manage content for a centralized web application"
    },
    {
      "claim": "Eligibility limited to US-based organizations; work performed offsite",
      "quote": "Eligibility: Onshore (USA Organization Only). Work Performance: Performance of the work will be offsite."
    },
    {
      "claim": "Proposal submission digital; question deadline November 2, 2026; proposal deadline December 10, 2026",
      "quote": "Proposal Submission: Response can be submitted digitally via Email or Online. Question Answer Deadline: Monday, 2 November, 2026. Expiry Date: Thursday, 10 December, 2026"
    }
  ]
}
